import { h, render, Component } from 'preact';

class CardItemVariable extends Component {

  constructor(props) {
    super(props);

  }

  componentDidMount() {
    let variable = this.props.variable;
    
    let units = variable.units;

    let unit_id = variable.unit_id;
    if (unit_id) {
      let exist = false;
      
      for (let i = 0; i < units.length; i++) {
        const unit = units[i];
        if (unit.id == unit_id) {
          exist = true;
          break;
        }
      }

      if (exist) {
        let element = `#unit-${ variable.id }`;
        $(element).val(unit_id);
      }
    }

    let rename = variable.rename;
    if (rename) {
      let element = `#name-${variable.id}`;
      $(element).val(rename);
    }    
  }

  handleRemove() {
    let self = this;

    let fn = () => {
      let variable = self.props.variable;
      let value = variable.id;

      let o = {
        variable_id: value,
        is_custom: variable.is_custom
      };

      self.props.onRemove(o);
    }

    return fn;
  }

  handleChangeUnit() {
    let self = this;

    let fn = (evt) => {
      let value = evt.target.value;

      let variable = self.props.variable;

      if (value == '') {
        value = undefined;
      } else {
        value = parseInt(value);
      }

      let o = {
        variable_id: variable.id,
        unit_id: value,
        is_custom: variable.is_custom
      };

      self.props.onChangeUnit(o);
    };

    return fn;
  }

  createOptUnit() {
    let self = this;

    let fn = (item, index) => {
      return <option key={index} value={item.id}>{item.name}</option>;
    };

    return fn;
  }

  render(props, state) {
    let variable = props.variable;
    
    let units = variable.units;
    if (!units) {
      units = [];
    }

    let unit = `unit-${variable.id}`;
    let nName = `name-${variable.id}`;

    return (
      <div className="col-md-3">
        <div className="card" style="margin: 5px 0px">
          <div className="card-body" style={{ padding: '0.3rem' }}>
            <table style={{ width: '100%', fontSize: '0.75rem' }}>
              <tbody>
                <tr>
                  <td colSpan="2" style="color:#333;">{variable.device}.{variable.name}</td>
                  <td colSpan="1" style="color:#333;">
                    <button type="button" className="close" data-dismiss="modal" aria-label="Close" onClick={this.handleRemove()}>
                      <span aria-hidden="true">&times;</span>
                    </button>
                  </td>
                </tr>
                <tr>
                  <td colSpan="3" style="color:#333;">
                    <input id={nName} type="text" className="form-control form-control-sm" placeholder="Nombre" />
                  </td>
                </tr>
                <tr>
                  <td colSpan="3" style="color:#333;">
                    <select id={unit} className="form-control form-control-sm" onChange={this.handleChangeUnit()}>
                      <option selected>Unidad</option>
                      {units.map(this.createOptUnit())}
                    </select>
                  </td>
                </tr>
              </tbody>
            </table>
          </div>
        </div>
      </div>
    );
  }
}

export default CardItemVariable;