import { h, render, Component } from 'preact';
import { isArray } from 'underscore';

import CardItemVariable from './card-item-variable.jsx';

class CardItemGroup extends Component {

  constructor(props) {
    super(props);

  }

  componentDidMount() {
  }

  handleSelected() {
    let self = this;

    let fn = (evt) => {
      let group = self.props.group;
      let value = group.id;

      let s = [];

      let parent = self.props.parent;
      if (parent) {
        s.push(parent);
      }

      if (value) {
        s.push(value);
      }

      if (group.isSelected) {
        self.props.onDeselected(s);
        return;
      }

      self.props.onSelected(s);
    }

    return fn;
  }

  handleOnSelected() {
    let self = this;

    let fn = (s) => {
      let a = [];

      let parent = self.props.parent;
      if (parent) {
        if (isArray(s)) {
          a.push(parent);
        }
      }

      for (let i = 0; i < s.length; i++) {
        a.push(s[i]);
      }

      self.props.onSelected(a);
    }

    return fn;
  }

  handleOnDeselected() {
    let self = this;

    let fn = (s) => {
      let a = [];

      let parent = self.props.parent;
      if (parent) {
        if (isArray(s)) {
          a.push(parent);
        }
      }

      for (let i = 0; i < s.length; i++) {
        a.push(s[i]);
      }

      self.props.onDeselected(a);
    }

    return fn;
  }  

  handleRemove() {
    let self = this;

    let fn = (evt) => {
      let group = self.props.group;
      let value = group.id;

      let s = [];

      let parent = self.props.parent;
      if (parent) {
        s.push(parent);
      }

      if (value) {
        s.push(value);
      }

      self.props.onRemove(s);
    }

    return fn;
  }

  handleOnRemove() {
    let self = this;

    let fn = (s) => {
      let a = [];

      let parent = self.props.parent;
      if (parent) {
        if (isArray(s)) {
          a.push(parent);
        }
      }

      for (let i = 0; i < s.length; i++) {
        a.push(s[i]);
      }

      self.props.onRemove(a);
    }

    return fn;
  }  

  handleRemoveVariable() {
    let self = this;

    let fn = (value) => {
      let group = self.props.group;
      let id = group.id;

      let s = [];

      let parent = self.props.parent;
      if (parent) {
        s.push(parent);
      }
      
      s.push(id);
      s.push(value);

      self.props.onRemoveVariable(s);
    }

    return fn;
  }

  handleOnRemoveVariable() {
    let self = this;

    let fn = (s) => {
      let a = [];

      let parent = self.props.parent;
      if (parent) {
        if (isArray(s)) {
          a.push(parent);
        }
      }

      for (let i = 0; i < s.length; i++) {
        a.push(s[i]);
      }

      self.props.onRemoveVariable(a);
    }

    return fn;
  }

  handleChangeUnit() {
    let self = this;

    let fn = (value) => {
      let group = self.props.group;
      let id = group.id;

      let s = [];

      let parent = self.props.parent;
      if (parent) {
        s.push(parent);
      }

      s.push(id);
      s.push(value);

      self.props.onChangeUnit(s);
    }

    return fn;
  }
  
  handleOnChangeUnit() {
    let self = this;

    let fn = (s) => {
      let a = [];

      let parent = self.props.parent;
      if (parent) {
        if (isArray(s)) {
          a.push(parent);
        }
      }

      for (let i = 0; i < s.length; i++) {
        a.push(s[i]);
      }

      self.props.onChangeUnit(a);
    }

    return fn;
  }

  createSons() {
    self = this;
    
    let group = self.props.group;

    let fn = (son, index) => {
      return <CardItemGroup key={index} group={son} parent={group.id} 
                onSelected={self.handleOnSelected()} 
                onDeselected={self.handleOnDeselected()} 
                onRemove={self.handleOnRemove()} 
                onRemoveVariable={self.handleOnRemoveVariable()}
                onChangeUnit={self.handleOnChangeUnit()} />;
    };

    return fn;
  }

  createvariables() {
    self = this;

    let group = self.props.group;

    let fn = (variable, index) => {
      return <CardItemVariable key={index} variable={variable} 
                onRemove={self.handleRemoveVariable()} 
                onChangeUnit={self.handleChangeUnit()} />;
    };

    return fn;
  }

  render(props, state) {
    let group = props.group;

    let sons = group.sons
    if (!sons) {
      sons = [];
    }

    let variables = group.variables;
    if (!variables) {
      variables = [];
    }    

    let classSelected = 'card bg-light mb-3';
    let styleContent = { padding: '0.5rem' };

    if (group.isSelected) {
      classSelected = `${classSelected} border-primary`;
    }

    return (
      <div className={classSelected}>
        <div className="card-header" style={styleContent}>
          <div className="row">
            <div className="col-md-10 col-sm-11 col-xs-11">
              <button style="padding: 0px;" type="button" className="btn btn-link" onClick={this.handleSelected()}>
                {group.name}
              </button>
            </div>
            <div className="col-md-2 col-sm-1 col-xs-1">
              <button type="button" className="close" data-dismiss="modal" aria-label="Close" onClick={this.handleRemove()}>
                <span aria-hidden="true">&times;</span>
              </button>
            </div>
          </div>
        </div>
        <div className="card-body ui-widget-header content-sons" style={{ padding: '0.5rem'}}>
          {sons.map(this.createSons())}
        </div>
        <div className="row">
          {variables.map(this.createvariables())}        
        </div>
      </div>
    );
  }
}

export default CardItemGroup;